<?php
defined( 'ABSPATH' ) || exit;
class CFP_Admin { public function hooks(): void { add_action('admin_menu',array($this,'menu')); add_action('admin_enqueue_scripts',array($this,'assets')); add_action('admin_post_cfp_create_funnel',array($this,'create_funnel')); } public function menu(): void { add_menu_page(__('ConversionFlow Pro','conversionflow-pro'),__('ConversionFlow','conversionflow-pro'),'manage_woocommerce','cfp-dashboard',array($this,'render'),'dashicons-randomize',56); foreach(array('funnels'=>'Funnels','store-checkout'=>'Store Checkout','analytics'=>'Analytics','templates'=>'Templates','automations'=>'Automations','emails'=>'Emails','file-delivery'=>'File Delivery','integrations'=>'Integrations','logs'=>'Logs','settings'=>'Settings') as $slug=>$label){ add_submenu_page('cfp-dashboard',__($label,'conversionflow-pro'),__($label,'conversionflow-pro'),'manage_woocommerce','cfp-'.$slug,array($this,'render')); } } public function assets(string $hook): void { if(false===strpos($hook,'cfp-')) return; wp_enqueue_style('cfp-admin',CFP_URL.'admin/assets/css/admin.css',array(),CFP_VERSION); wp_enqueue_script('cfp-admin',CFP_URL.'admin/assets/js/admin.js',array('jquery'),CFP_VERSION,true); } public function create_funnel(): void { CFP_Security::verify_admin('cfp_create_funnel'); $name=sanitize_text_field(wp_unslash($_POST['funnel_name']??'')); $type=sanitize_key(wp_unslash($_POST['funnel_type']??'sales')); $steps=array_map('sanitize_key',(array)($_POST['steps']??array('landing','checkout','thank_you'))); $id=(new CFP_Funnels())->create($name?:__('Untitled Funnel','conversionflow-pro'),$type,$steps); wp_safe_redirect(admin_url('admin.php?page=cfp-funnels&funnel_id='.$id)); exit; } public function render(): void { include CFP_PATH.'admin/views/dashboard.php'; } }
